void ReadSector ( char *src, int ss, int num, void* buff )
{

HANDLE h ;

unsigned int br ;

h = CreateFile ( src, GENERIC_READ,

FILE_SHARE_READ, 0, OPEN_EXISTING, 0, 0 ) ;

SetFilePointer ( h, ( ss * 512 ), NULL, FILE_BEGIN ) ;

ReadFile ( h, buff, 512 * num, &br, NULL ) )

CloseHandle ( h ) ;

}

